import argparse

from fastapi import FastAPI, Header, HTTPException
from pydantic import BaseModel, Field

from app.rules import order_rules
from app.store import orders
from app.store.db import connect, migrate
from app.usecase import orders as orders_uc

app = FastAPI(title="settlement-ledger")

IDEMPOTENCY_HEADER = "Idempotency-Key"

class OrderIn(BaseModel):
    tenant: str = Field(min_length=1)
    order_id: str = Field(min_length=1)
    amount_cents: int = Field(gt=0)
    currency: str = Field(min_length=3, max_length=3)

class PaymentIn(BaseModel):
    amount_cents: int = Field(gt=0)

@app.get("/health")
def health() -> dict:
    conn = connect()
    try:
        conn.execute("SELECT 1")
    finally:
        conn.close()
    return {"status": "ok"}

@app.post("/orders", status_code=201)
def create_order(body: OrderIn, idempotency_key: str = Header(default="", alias=IDEMPOTENCY_HEADER)) -> dict:
    try:
        order_rules.assert_currency(body.currency)
    except ValueError as error:
        raise HTTPException(status_code=400, detail=str(error))

    if not idempotency_key:
        # 未携带请求标识：保持原有处理方式
        try:
            orders.insert(body.tenant, body.order_id, body.amount_cents, body.currency)
        except Exception as error:
            if "UNIQUE" in str(error):
                raise HTTPException(status_code=409, detail="order already accepted")
            raise
        return orders.get(body.tenant, body.order_id)

    try:
        result = orders_uc.accept_order(
            body.tenant, idempotency_key, body.order_id, body.amount_cents, body.currency
        )
    except orders_uc.IdempotentConflict as error:
        raise HTTPException(status_code=422, detail=str(error))
    if result.status_code != 201:
        raise HTTPException(status_code=result.status_code, detail=result.body.get("detail"))
    return result.body

@app.get("/orders/{order_id}")
def read_order(order_id: str, x_tenant: str = Header(default="")) -> dict:
    tenant = x_tenant or ""
    if not tenant:
        raise HTTPException(status_code=400, detail="tenant header is required")
    order = orders.get(tenant, order_id)
    if order is None:
        raise HTTPException(status_code=404, detail="order not found")
    return order

@app.post("/orders/{order_id}/payments")
def add_payment(
    order_id: str,
    body: PaymentIn,
    x_tenant: str = Header(default=""),
    idempotency_key: str = Header(default="", alias=IDEMPOTENCY_HEADER),
) -> dict:
    if not x_tenant:
        raise HTTPException(status_code=400, detail="tenant header is required")

    if not idempotency_key:
        # 未携带请求标识：保持原有处理方式
        try:
            order = orders.add_payment(x_tenant, order_id, body.amount_cents)
        except ValueError as error:
            raise HTTPException(status_code=409, detail=str(error))
        if order is None:
            raise HTTPException(status_code=404, detail="order not found")
        return order

    try:
        result = orders_uc.register_payment(x_tenant, idempotency_key, order_id, body.amount_cents)
    except orders_uc.IdempotentConflict as error:
        raise HTTPException(status_code=422, detail=str(error))
    if result.status_code != 200:
        raise HTTPException(status_code=result.status_code, detail=result.body.get("detail"))
    return result.body

def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--port", type=int, default=8000)
    parser.add_argument("--migrate", action="store_true")
    args = parser.parse_args()
    migrate()
    if args.migrate:
        print("migrated")
        return
    import uvicorn
    uvicorn.run(app, host="127.0.0.1", port=args.port)

if __name__ == "__main__":
    main()

import os
from pathlib import Path


def db_path() -> Path:
    return Path(os.environ.get("APP_DB", "var/app.sqlite"))

def tenant_header() -> str:
    return os.environ.get("APP_TENANT_HEADER", "X-Tenant")

ALLOWED_CURRENCIES = {"CNY", "USD", "EUR", "JPY"}

def assert_currency(currency: str) -> None:
    if currency not in ALLOWED_CURRENCIES:
        raise ValueError("unsupported currency")

import sqlite3

from app.store.db import connect

ORDER_COLUMNS = "tenant, order_id, amount_cents, paid_cents, currency, status"

def _row_to_order(row: sqlite3.Row) -> dict:
    return {**dict(row), "outstanding_cents": row["amount_cents"] - row["paid_cents"]}

def insert_conn(conn: sqlite3.Connection, tenant: str, order_id: str, amount_cents: int, currency: str) -> None:
    """在调用方给定的连接/事务内受理订单。"""
    conn.execute(
        f"INSERT INTO orders({ORDER_COLUMNS}) VALUES(?,?,?,0,?,'accepted')",
        (tenant, order_id, amount_cents, currency),
    )

def get_conn(conn: sqlite3.Connection, tenant: str, order_id: str) -> dict | None:
    row = conn.execute(
        f"SELECT {ORDER_COLUMNS} FROM orders WHERE tenant=? AND order_id=?",
        (tenant, order_id),
    ).fetchone()
    if row is None:
        return None
    return _row_to_order(row)

def pay_conn(conn: sqlite3.Connection, tenant: str, order_id: str, amount_cents: int) -> dict:
    """在调用方给定的写事务内登记收款。

    订单不存在抛 LookupError；超过未收金额抛 ValueError；成功返回更新后的订单。
    """
    row = conn.execute(
        "SELECT amount_cents, paid_cents FROM orders WHERE tenant=? AND order_id=?",
        (tenant, order_id),
    ).fetchone()
    if row is None:
        raise LookupError("order not found")
    if amount_cents <= 0 or row["paid_cents"] + amount_cents > row["amount_cents"]:
        raise ValueError("payment exceeds outstanding amount")
    conn.execute(
        "UPDATE orders SET paid_cents = paid_cents + ?, "
        "status = CASE WHEN paid_cents + ? >= amount_cents THEN 'settled' ELSE 'accepted' END "
        "WHERE tenant=? AND order_id=?",
        (amount_cents, amount_cents, tenant, order_id),
    )
    updated = get_conn(conn, tenant, order_id)
    assert updated is not None
    return updated

def insert(tenant: str, order_id: str, amount_cents: int, currency: str) -> None:
    conn = connect()
    try:
        insert_conn(conn, tenant, order_id, amount_cents, currency)
    finally:
        conn.close()

def get(tenant: str, order_id: str) -> dict | None:
    conn = connect()
    try:
        return get_conn(conn, tenant, order_id)
    finally:
        conn.close()

def add_payment(tenant: str, order_id: str, amount_cents: int) -> dict | None:
    conn = connect()
    try:
        conn.execute("BEGIN IMMEDIATE")
        try:
            order = pay_conn(conn, tenant, order_id, amount_cents)
        except LookupError:
            conn.execute("ROLLBACK")
            return None
        except Exception:
            conn.execute("ROLLBACK")
            raise
        conn.execute("COMMIT")
    finally:
        conn.close()
    return order

"""幂等用例：同一租户内同一请求标识只产生一次业务效果。

并发语义依赖 SQLite 的 BEGIN IMMEDIATE：同一时刻只有一个请求能进入写事务，
后来的同标识请求在锁释放后读到的必然是已提交的首次记录，从而回放首次结果。
"""
import hashlib
import json
import sqlite3

from app.store import idempotency, orders
from app.store.db import connect

SCOPE_ORDER_CREATE = "order_create"
SCOPE_PAYMENT = "payment"


class IdempotentConflict(Exception):
    """同一请求标识对应了与首次不同的业务内容，或被用于不同类型的操作。"""


class IdemResult:
    def __init__(self, status_code: int, body: dict, replay: bool):
        self.status_code = status_code
        self.body = body
        self.replay = replay


def _fingerprint(parts: tuple) -> str:
    raw = json.dumps(parts, ensure_ascii=False, separators=(",", ":"), sort_keys=True)
    return hashlib.sha256(raw.encode("utf-8")).hexdigest()


def _finish(conn: sqlite3.Connection) -> None:
    conn.execute("COMMIT")


def _abort(conn: sqlite3.Connection) -> None:
    conn.execute("ROLLBACK")


def accept_order(tenant: str, request_id: str, order_id: str, amount_cents: int, currency: str) -> IdemResult:
    request_hash = _fingerprint((SCOPE_ORDER_CREATE, order_id, amount_cents, currency))
    conn = connect()
    try:
        conn.execute("BEGIN IMMEDIATE")
        existing = idempotency.get_conn(conn, tenant, request_id)
        if existing is not None:
            _finish(conn)
            if existing["scope"] != SCOPE_ORDER_CREATE or existing["request_hash"] != request_hash:
                raise IdempotentConflict("request id was already used with different request content")
            return IdemResult(existing["status_code"], json.loads(existing["response_json"]), replay=True)

        try:
            try:
                orders.insert_conn(conn, tenant, order_id, amount_cents, currency)
                status_code, body = 201, orders.get_conn(conn, tenant, order_id)
            except sqlite3.IntegrityError:
                # 同一租户重复受理（未携带本请求标识的既有订单/或首次结果即冲突）
                status_code, body = 409, {"detail": "order already accepted"}
            idempotency.insert_conn(
                conn, tenant, request_id, SCOPE_ORDER_CREATE, request_hash, order_id,
                status_code, json.dumps(body, ensure_ascii=False),
            )
            _finish(conn)
        except Exception:
            _abort(conn)
            raise
    finally:
        conn.close()
    return IdemResult(status_code, body, replay=False)


def register_payment(tenant: str, request_id: str, order_id: str, amount_cents: int) -> IdemResult:
    request_hash = _fingerprint((SCOPE_PAYMENT, order_id, amount_cents))
    conn = connect()
    try:
        conn.execute("BEGIN IMMEDIATE")
        existing = idempotency.get_conn(conn, tenant, request_id)
        if existing is not None:
            _finish(conn)
            if existing["scope"] != SCOPE_PAYMENT or existing["request_hash"] != request_hash:
                raise IdempotentConflict("request id was already used with different request content")
            return IdemResult(existing["status_code"], json.loads(existing["response_json"]), replay=True)

        try:
            try:
                body = orders.pay_conn(conn, tenant, order_id, amount_cents)
                status_code = 200
            except LookupError:
                status_code, body = 404, {"detail": "order not found"}
            except ValueError as error:
                status_code, body = 409, {"detail": str(error)}
            idempotency.insert_conn(
                conn, tenant, request_id, SCOPE_PAYMENT, request_hash, order_id,
                status_code, json.dumps(body, ensure_ascii=False),
            )
            _finish(conn)
        except Exception:
            _abort(conn)
            raise
    finally:
        conn.close()
    return IdemResult(status_code, body, replay=False)

import os
import tempfile

os.environ.setdefault("APP_DB", os.path.join(tempfile.mkdtemp(), "test.sqlite"))
from fastapi.testclient import TestClient

from app.entry import app
from app.store.db import migrate

migrate()
client = TestClient(app)

def test_accept_and_read_order() -> None:
    body = {"tenant": "t1", "order_id": "o1", "amount_cents": 500, "currency": "CNY"}
    assert client.post("/orders", json=body).status_code == 201
    got = client.get("/orders/o1", headers={"X-Tenant": "t1"})
    assert got.status_code == 200 and got.json()["outstanding_cents"] == 500

def test_duplicate_is_refused() -> None:
    body = {"tenant": "t1", "order_id": "o2", "amount_cents": 100, "currency": "CNY"}
    assert client.post("/orders", json=body).status_code == 201
    assert client.post("/orders", json=body).status_code == 409

def test_cross_tenant_read_is_not_found() -> None:
    body = {"tenant": "t1", "order_id": "o3", "amount_cents": 100, "currency": "CNY"}
    client.post("/orders", json=body)
    assert client.get("/orders/o3", headers={"X-Tenant": "t2"}).status_code == 404

def test_payment_cannot_exceed_outstanding() -> None:
    body = {"tenant": "t1", "order_id": "o4", "amount_cents": 300, "currency": "CNY"}
    client.post("/orders", json=body)
    assert client.post("/orders/o4/payments", json={"amount_cents": 100}, headers={"X-Tenant": "t1"}).status_code == 200
    assert client.post("/orders/o4/payments", json={"amount_cents": 500}, headers={"X-Tenant": "t1"}).status_code == 409

